theorem lg_target (a : ℤ) : a ^ 2 % 4 = 0 ∨ a ^ 2 % 4 = 1 := by
  cases Int.emod_two_eq_zero_or_one a with h0 h1;
  obtain ⟨h0', h1'⟩ := h0;
  constructor;
  · rw [Int.emod_eq_mod];
    rw [Int.mod_sq];
    rw [Int.mod_two_zero];
    exact rfl;
  · rw [Int.emod_eq_mod];
    rw [Int.mod_sq];
    rw [Int.mod_two_one];
    exact rfl
